.datepicker-trigger {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  min-inline-size: 12rem;
  block-size: var(--control-height);
  padding-inline: var(--control-padding-x);
  background: var(--background);
  color: var(--foreground);
  border: 1px solid var(--input);
  border-radius: var(--control-radius);
  font-size: var(--control-font-size);
  transition: border-color var(--duration-fast);
}
.datepicker-trigger[data-size="sm"] { block-size: var(--control-height-sm); padding-inline: var(--space-3); font-size: var(--font-sm); }
.datepicker-trigger[data-size="lg"] { block-size: var(--control-height-lg); font-size: var(--control-font-size-lg); }
.datepicker-trigger:hover { border-color: var(--ring); }
/* Pressed: one stop past hover, the third answer every control now gives. */
.datepicker-trigger:active:not(:disabled) { border-color: var(--primary-active); }
.datepicker-trigger[data-invalid] { border-color: var(--destructive); }
.datepicker-trigger[data-invalid]:focus-visible { outline-color: var(--destructive); }
/* --muted surface: drop the resting border (invalid + focus outline still show). */
.datepicker-trigger[data-surface="muted"]:not([data-invalid]),
.datepicker-trigger[data-surface="muted"]:not([data-invalid]):hover { border-color: transparent; }
.datepicker-trigger[data-placeholder] { color: var(--muted-foreground); }
.datepicker-trigger:disabled { opacity: var(--disabled-opacity); cursor: not-allowed; }
.datepicker-icon { color: var(--icon-muted); }

/* MONOLITHIC BECAUSE IT IS A FIELD PLUS THE DATE DOMAIN.
 *
 * Seven of these are the field contract every control in this system carries —
 * label, id, placeholder, invalid, surface, size, disabled — and the rest are
 * the dates: which exist (`min`, `max`), which is chosen, in whose language.
 * A compound would separate a control from its own validity.
 *
 * What the split would cost: the same field contract expressed twice, once on
 * the trigger and once on the panel, with nothing holding them in step.
 * (2026-09-03)
 */
import './DatePicker.css'
import { useState } from 'react'
import { cn } from '../lib/cn'
import { Calendar } from '../Calendar'
import { Icon } from '../Icon'
import { Popover } from '../Popover'

type Props = {
  value?: Date
  onChange: (date: Date) => void
  min?: Date
  max?: Date
  /** Accessible name for the trigger. */
  label: string
  /** Lands on the trigger, so `<Field htmlFor>` reaches it and an `ErrorSummary`
   *  row can put focus on it (see Select — same gap, same day). */
  id?: string
  placeholder?: string
  /** BCP-47 locale for the shown date + the calendar. Defaults to document lang. */
  locale?: string
  /** A STATE, not a style: it turns the border and hands <Field> the hook it needs to read the
   *  error out as part of the field.
   */
  invalid?: boolean
  /** Which surface the field sits on. On `muted` (a page/PageHeader) the border
   *  is dropped since the white fill separates it; `base` (default, a white card
   *  or form) keeps the border. Invalid + focus stay visible on both. */
  surface?: 'base' | 'muted'
  /** sm / md (default) / lg — matches the shared control height/padding scale. */
  size?: 'sm' | 'md' | 'lg'
  /** Dimmed and unpressable, but pointer events are KEPT so a Tooltip can say why. A control the
   *  reader cannot use and cannot ask about is a dead end.
   */
  disabled?: boolean
  className?: string
}

/* A date field: a trigger that reads like an input and opens a <Calendar> in a
 * <Popover>. Picking a day sets the value and closes. The shown date is
 * formatted with Intl; the calendar carries the keyboard contract. 
   *
   * Copy: the label names the event, not the field — "Delivery date". The
   * placeholder shows the format the reader may type, and it is the format
   * their locale writes.
   */
export function DatePicker({
  value, onChange, min, max, label, id, placeholder = 'Select date',
  locale = typeof document !== 'undefined' ? document.documentElement.lang || 'en' : 'en',
  invalid, disabled, surface = 'base', size, className,
}: Props) {
  const [key, setKey] = useState(0) // remount the Popover to close it on pick
  const fmt = new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'short', year: 'numeric' })
  const shown = value ? fmt.format(value) : placeholder

  return (
    <Popover
      key={key}
      label={label}
      trigger={(props) => (
        <button
          type="button"
          id={id}
          className={cn('datepicker-trigger', className)}
          data-invalid={invalid || undefined}
          data-surface={surface}
          data-size={size}
          data-placeholder={!value || undefined}
          disabled={disabled}
          aria-label={label}
          {...props}
        >
          <Icon name="calendar" className="datepicker-icon" />
          <span>{shown}</span>
        </button>
      )}
    >
      <Calendar
        value={value}
        min={min}
        max={max}
        locale={locale}
        onChange={(d) => { onChange(d); setKey((k) => k + 1) }}
      />
    </Popover>
  )
}
